class Solution {
    public int majorityElement(int[] nums) {
        int candidate = nums[0];
        int count = 0;

        for (int num : nums) {
            if (count == 0) {
                candidate = num;
            }
            count += (num == candidate) ? 1 : -1;
        }

        return candidate;
    }
}

class Solution {
    public int majorityElement(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        int threshold = nums.length / 2;

        for (int num : nums) {
            int count = counts.getOrDefault(num, 0) + 1;
            if (count > threshold) {
                return num;
            }
            counts.put(num, count);
        }

        return nums[0];
    }
}

class Solution {
    public int majorityElement(int[] nums) {
        Arrays.sort(nums);
        return nums[nums.length / 2];
    }
}

class Solution {
    public int majorityElement(int[] nums) {
        return majority(nums, 0, nums.length - 1);
    }

    private int majority(int[] nums, int left, int right) {
        if (left == right) {
            return nums[left];
        }

        int mid = left + (right - left) / 2;
        int leftCandidate = majority(nums, left, mid);
        int rightCandidate = majority(nums, mid + 1, right);
        if (leftCandidate == rightCandidate) {
            return leftCandidate;
        }

        int leftCount = countInRange(nums, leftCandidate, left, right);
        int rightCount = countInRange(nums, rightCandidate, left, right);
        return leftCount > rightCount ? leftCandidate : rightCandidate;
    }

    private int countInRange(int[] nums, int value, int left, int right) {
        int count = 0;
        for (int i = left; i <= right; i++) {
            if (nums[i] == value) {
                count++;
            }
        }
        return count;
    }
}
